profiles.css:
.sf-atelier { padding: 24px 0; }
.sf-atelier__inner { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: center; gap: 24px; }
.sf-atelier h2 { font-size: 20px; line-height: 1.55; }
.sf-atelier p { line-height: 1.9; color: #4b555d; }
.sf-atelier__image { margin: 0; }
.sf-atelier__image img { width: 100%; height: auto; }
.sf-atelier--image-left .sf-atelier__image { grid-column: 1; grid-row: 1; }
.sf-atelier--image-left .sf-atelier__body { grid-column: 2; }
.sf-atelier--stacked .sf-atelier__inner { grid-template-columns: minmax(0, 1fr); }
@media (max-width: 430px) {
  .sf-atelier__inner { grid-template-columns: minmax(0, 1fr); }
  .sf-atelier--image-left .sf-atelier__body { grid-column: auto; }
  .sf-atelier--image-left .sf-atelier__image { grid-column: auto; grid-row: auto; }
}
